// Merge session data with message data
const sessionData = $input.item.json.value ? JSON.parse($input.item.json.value) : null;
const messageData = $('Parsear Mensagem').item.json;

if (sessionData) {
  return {
    ...messageData,
    session: sessionData,
    hasSession: true
  };
} else {
  return {
    ...messageData,
    session: null,
    hasSession: false
  };
}

// Processar mensagem e determinar intenção
const message = ($json.message || '').toLowerCase().trim();
const session = $json.session || { step: 'greeting', context: {} };

// Intenções
let intent = 'greeting';
let nextStep = session.step;

if (message.includes('agendar') || message.includes('consulta') || message.includes('marcar')) {
  intent = 'schedule';
  nextStep = 'schedule_service';
} else if (message.includes('serviço') || message.includes('quiro') || message.includes('medicina') || message.includes('acupuntura')) {
  intent = 'service_info';
  nextStep = 'service_info';
} else if (message.includes('preço') || message.includes('valor') || message.includes('custo')) {
  intent = 'pricing';
  nextStep = 'pricing';
} else if (message.includes('horário') || message.includes('funciona') || message.includes('aberto')) {
  intent = 'hours';
  nextStep = 'hours';
} else if (message.includes('dúvida') || message.includes('pergunta') || message.includes('faq')) {
  intent = 'faq';
  nextStep = 'faq';
} else if (message.includes('cancelar') || message.includes('desmarcar')) {
  intent = 'cancel';
  nextStep = 'cancel';
} else if (session.step === 'schedule_service') {
  nextStep = 'schedule_date';
} else if (session.step === 'schedule_date') {
  nextStep = 'schedule_time';
} else if (session.step === 'schedule_time') {
  nextStep = 'schedule_confirm';
}

return {
  ...$json,
  intent,
  nextStep,
  processedAt: new Date().toISOString()
};

// RAG - Retrieval Augmented Generation
// Buscar informações relevantes dos serviços
const message = ($json.message || '').toLowerCase();
const services = $('Supabase - Buscar Serviços').item.json || [];
const cachedData = $('Redis - Cache RAG').item.json?.value;

// Dados de serviços (fallback se não tiver no Supabase)
const servicesData = cachedData ? JSON.parse(cachedData) : {
  quiropraxia: {
    title: 'Quiropraxia',
    description: 'Ajustes vertebrais e correção postural para alívio de dores e melhoria da função do sistema nervoso.',
    content: 'A quiropraxia é uma profissão da área da saúde que se concentra no diagnóstico, tratamento e prevenção de distúrbios do sistema musculoesquelético, especialmente da coluna vertebral.',
    whatToExpect: [
      'Avaliação inicial completa da postura e da coluna',
      'Análise de movimentos e amplitude de movimento',
      'Ajustes quiropráticos específicos e controlados',
      'Orientações sobre exercícios e cuidados posturais'
    ],
    whoItHelps: [
      'Pessoas com dores nas costas, pescoço ou ombros',
      'Indivíduos com problemas posturais',
      'Pessoas que sofrem de dores de cabeça tensionais',
      'Atletas buscando melhor performance e recuperação'
    ]
  },
  'medicina-oriental': {
    title: 'Medicina Oriental e Terapias Integrativas',
    description: 'Terapias integrativas baseadas na medicina tradicional chinesa e outras práticas orientais.',
    content: 'A medicina oriental oferece uma visão holística da saúde, focando no equilíbrio energético do corpo.',
    therapies: [
      { name: 'Acupuntura', description: 'Técnica milenar que utiliza agulhas finas em pontos específicos do corpo.' },
      { name: 'Ventosaterapia', description: 'Aplicação de ventosas para melhorar circulação e reduzir tensão muscular.' },
      { name: 'Moxabustão', description: 'Técnica de aquecimento de pontos de acupuntura para fortalecer o sistema imunológico.' }
    ]
  }
};

// Detectar qual serviço o usuário está perguntando
let relevantService = null;
if (message.includes('quiro') || message.includes('coluna') || message.includes('postura')) {
  relevantService = servicesData.quiropraxia || servicesData.find(s => s.slug === 'quiropraxia');
} else if (message.includes('medicina') || message.includes('oriental') || message.includes('acupuntura') || message.includes('ventosa')) {
  relevantService = servicesData['medicina-oriental'] || servicesData.find(s => s.slug === 'medicina-oriental');
}

// Gerar resposta contextual
let response = '';
if (relevantService) {
  response = `*${relevantService.title}*\n\n${relevantService.description}\n\n`;

  if (relevantService.whatToExpect) {
    response += '*O que esperar:*\n';
    relevantService.whatToExpect.forEach(item => {
      response += `• ${item}\n`;
    });
  }

  if (relevantService.therapies) {
    response += '\n*Terapias oferecidas:*\n';
    relevantService.therapies.forEach(therapy => {
      response += `• *${therapy.name}*: ${therapy.description}\n`;
    });
  }

  if (relevantService.whoItHelps) {
    response += '\n*Para quem é indicado:*\n';
    relevantService.whoItHelps.forEach(item => {
      response += `• ${item}\n`;
    });
  }

  response += '\nGostaria de agendar uma consulta? Digite *agendar* para começar.';
} else {
  response = '*Nossos Serviços:*\n\n';
  response += '*1. Quiropraxia*\n';
  response += 'Ajustes vertebrais e correção postural\n\n';
  response += '*2. Medicina Oriental*\n';
  response += 'Acupuntura, Ventosaterapia e Moxabustão\n\n';
  response += 'Sobre qual serviço gostaria de saber mais? Ou digite *agendar* para marcar uma consulta.';
}

return {
  ...$json,
  ragResponse: response,
  relevantService: relevantService?.title || 'Geral'
};

// Gerenciar fluxo de agendamento
const session = $json.session || { step: 'greeting', context: {} };
const message = ($json.message || '').toLowerCase().trim();
const step = $json.nextStep || session.step;

let response = '';
let updatedContext = { ...session.context };
let updatedStep = step;

if (step === 'schedule_service') {
  response = '*Agendamento de Consulta*\n\n';
  response += 'Qual serviço você gostaria de agendar?\n\n';
  response += '*1* - Quiropraxia\n';
  response += '*2* - Medicina Oriental\n';
  response += '*3* - Ambos\n\n';
  response += 'Digite o número da opção desejada.';

} else if (step === 'schedule_date') {
  // Processar seleção de serviço
  if (message === '1' || message.includes('quiro')) {
    updatedContext.service = 'Quiropraxia';
  } else if (message === '2' || message.includes('medicina') || message.includes('oriental')) {
    updatedContext.service = 'Medicina Oriental';
  } else if (message === '3' || message.includes('ambos')) {
    updatedContext.service = 'Quiropraxia + Medicina Oriental';
  }

  if (updatedContext.service) {
    response = `Ótimo! Você escolheu: *${updatedContext.service}*\n\n`;
    response += 'Qual data você prefere?\n';
    response += 'Digite a data no formato DD/MM/AAAA ou escolha:\n';
    response += '*hoje* - Para hoje\n';
    response += '*amanhã* - Para amanhã\n';
    response += '*próxima semana* - Para próxima semana';
    updatedStep = 'schedule_time';
  } else {
    response = 'Por favor, escolha uma opção válida (1, 2 ou 3).';
  }

} else if (step === 'schedule_time') {
  // Processar data
  const today = new Date();
  let selectedDate = null;

  if (message === 'hoje') {
    selectedDate = today;
  } else if (message === 'amanhã') {
    selectedDate = new Date(today.getTime() + 24 * 60 * 60 * 1000);
  } else if (message.includes('/')) {
    const parts = message.split('/');
    if (parts.length === 3) {
      selectedDate = new Date(parseInt(parts[2]), parseInt(parts[1]) - 1, parseInt(parts[0]));
    }
  }

  if (selectedDate && selectedDate >= today) {
    updatedContext.date = selectedDate.toISOString().split('T')[0];
    response = `Data selecionada: *${selectedDate.toLocaleDateString('pt-BR')}*\n\n`;
    response += 'Qual horário você prefere?\n\n';
    response += '*16:00* - Digite 1\n';
    response += '*17:00* - Digite 2\n\n';
    response += 'Ou digite um horário no formato HH:MM';
    updatedStep = 'schedule_confirm';
  } else {
    response = 'Por favor, digite uma data válida no formato DD/MM/AAAA ou escolha uma das opções.';
  }

} else if (step === 'schedule_confirm') {
  // Processar horário
  let selectedTime = null;

  if (message === '1') {
    selectedTime = '16:00';
  } else if (message === '2') {
    selectedTime = '17:00';
  } else if (message.match(/^\d{2}:\d{2}$/)) {
    selectedTime = message;
  }

  if (selectedTime) {
    updatedContext.time = selectedTime;
    response = `*Resumo do Agendamento*\n\n`;
    response += `Serviço: *${updatedContext.service}*\n`;
    response += `Data: *${updatedContext.date}*\n`;
    response += `Horário: *${selectedTime}*\n\n`;
    response += 'Para confirmar, preciso de algumas informações:\n';
    response += 'Digite seu *nome completo*:';
    updatedStep = 'schedule_name';
  } else {
    response = 'Por favor, digite um horário válido (ex: 16:00 ou 17:00).';
  }

} else if (step === 'schedule_name') {
  updatedContext.name = message;
  response = `Obrigado, ${message}!\n\n`;
  response += 'Agora digite seu *telefone* (com DDD):';
  updatedStep = 'schedule_phone';

} else if (step === 'schedule_phone') {
  updatedContext.phone = message.replace(/\D/g, '');
  response = 'Perfeito!\n\n';
  response += 'Digite seu *e-mail* (opcional, pode digitar *pular*):';
  updatedStep = 'schedule_email';

} else if (step === 'schedule_email') {
  if (message !== 'pular' && message.includes('@')) {
    updatedContext.email = message;
  }

  // Agendamento completo - criar no Google Calendar
  updatedStep = 'schedule_complete';
  response = 'Aguarde, estou criando seu agendamento...';
}

return {
  ...$json,
  scheduleResponse: response,
  scheduleContext: updatedContext,
  scheduleStep: updatedStep
};

// Gerar resposta padrão baseada na intenção
const intent = $json.intent;
const session = $json.session || { step: 'greeting' };

let response = '';

if (intent === 'greeting' || session.step === 'greeting') {
  response = '👋 *Olá! Bem-vindo à Clínica J.Melo*\n\n';
  response += 'Como posso ajudá-lo hoje?\n\n';
  response += '*1* - Informações sobre serviços\n';
  response += '*2* - Agendar consulta\n';
  response += '*3* - Dúvidas frequentes\n';
  response += '*4* - Horários de funcionamento\n';
  response += '*5* - Valores\n\n';
  response += 'Digite o número da opção ou sua pergunta.';

} else if (intent === 'pricing') {
  response = '*Valores*\n\n';
  response += '• *Quiropraxia*: R$ 150,00\n';
  response += '• *Medicina Oriental*: R$ 120,00\n';
  response += '• *Pacote (3 sessões)*: R$ 350,00\n\n';
  response += 'Gostaria de agendar? Digite *agendar*';

} else if (intent === 'hours') {
  response = '*Horários de Funcionamento*\n\n';
  response += 'Segunda a Sexta: 16h às 18h\n';
  response += 'Sábado: 9h às 12h\n';
  response += 'Domingo: Fechado\n\n';
  response += 'Gostaria de agendar? Digite *agendar*';

} else if (intent === 'faq') {
  response = '*Dúvidas Frequentes*\n\n';
  response += '1. Quiropraxia dói?\n';
  response += '2. Quantas sessões preciso?\n';
  response += '3. Como funciona a primeira consulta?\n';
  response += '4. Atende convênio?\n\n';
  response += 'Digite o número da pergunta ou faça sua própria pergunta.';

} else {
  response = 'Desculpe, não entendi. Como posso ajudá-lo?\n\n';
  response += 'Digite *agendar* para marcar uma consulta ou *serviços* para conhecer nossos serviços.';
}

return {
  ...$json,
  defaultResponse: response
};

// Consolidar resposta final
let finalResponse = '';

if ($json.ragResponse) {
  finalResponse = $json.ragResponse;
} else if ($json.scheduleResponse) {
  finalResponse = $json.scheduleResponse;

  // Se agendamento completo, adicionar confirmação
  if ($json.scheduleStep === 'schedule_complete') {
    const calendarEvent = $('Google Calendar - Criar Evento')?.item?.json;
    if (calendarEvent) {
      finalResponse = '✅ *Agendamento Confirmado!*\n\n';
      finalResponse += `Serviço: *${$json.scheduleContext.service}*\n`;
      finalResponse += `Data: *${new Date($json.scheduleContext.date).toLocaleDateString('pt-BR')}*\n`;
      finalResponse += `Horário: *${$json.scheduleContext.time}*\n\n`;
      finalResponse += 'Seu agendamento foi criado no nosso sistema.\n';
      finalResponse += 'Em breve entraremos em contato para confirmar.\n\n';
      finalResponse += 'Obrigado por escolher a Clínica J.Melo! 🎉';
    }
  }
} else if ($json.defaultResponse) {
  finalResponse = $json.defaultResponse;
} else {
  finalResponse = 'Olá! Como posso ajudá-lo hoje?';
}

// Atualizar sessão no Redis
const session = $json.session || { step: 'greeting', context: {} };
const updatedStep = $json.scheduleStep || $json.nextStep || session.step;
const updatedContext = $json.scheduleContext || session.context;

const updatedSession = {
  phone: $json.phone,
  step: updatedStep,
  context: updatedContext,
  lastMessage: $json.message,
  lastResponse: finalResponse,
  updatedAt: new Date().toISOString()
};

return {
  ...$json,
  finalResponse,
  updatedSession
};
